Import-Module "$PSScriptRoot\..\src\Collection.psm1" -Force
Test 'Old generation ignored' { Assert-Equal (Test-CollectionResultCurrent @{Generation=1;StartedUtc='2026-10-11T12:00:00Z'} 2 '2026-10-11T11:00:00Z') $false; Assert-True (Test-CollectionResultCurrent @{Generation=2;StartedUtc='2026-10-11T12:00:00Z'} 2 '2026-10-11T11:00:00Z') }
Test 'Older response ignored' { Assert-Equal (Test-CollectionResultCurrent @{Generation=2;StartedUtc='2026-10-11T10:00:00Z'} 2 '2026-10-11T11:00:00Z') $false }
Test 'Failed source retains timestamp' { $old=@{Status='connected';ObservedAtUtc='2026-10-11T11:00:00Z';RemainingPercent=15}; $m=Merge-MeasureFailure $old @{Status='error';Source='Falha';Message='Erro'}; Assert-Equal $m.ObservedAtUtc $old.ObservedAtUtc; Assert-Equal $m.RemainingPercent 15; Assert-Equal $m.Status 'stale' }
Test 'Recuo limitado e Retry-After' { Assert-Equal (Get-RetryDelay 1 0) 60; Assert-Equal (Get-RetryDelay 8 0) 900; Assert-Equal (Get-RetryDelay 1 300) 300 }
Test 'Cost without budget retained and server retry preserved' { $old=@{Status='connected';RemainingPercent=$null;SpentMonthUsd=90;ObservedAtUtc='2026-10-11T11:00:00Z'};$m=Merge-MeasureFailure $old @{Status='error';RetryAfter=600;Message='Falha'};Assert-Equal $m.SpentMonthUsd 90;Assert-Equal $m.ObservedAtUtc $old.ObservedAtUtc;Assert-Equal $m.RetryAfter 600;Assert-True (Test-ProviderCollectionFailed @{Subscription=@{Status='stale'};Api=@{Status='unconfigured'}}) }
Test 'Refresh schedules without mutating observed timestamp' { $state=@{Snapshots=@{codex=@{Api=@{ObservedAtUtc='2026-10-11T11:00:00Z'}}};NextCollection=@{};ForceRefresh=@{}};Request-ProviderRefresh $state 'codex';Assert-Equal $state.Snapshots.codex.Api.ObservedAtUtc '2026-10-11T11:00:00Z';Assert-True $state.ForceRefresh.codex }
